function useLS(key,init){const[data,set]=useState(()=>{try{const s=localStorage.getItem("lp_c_"+key);return s?JSON.parse(s):init;}catch{return init;}});const save=useCallback(val=>{const next=typeof val==="function"?val(data):val;set(next);try{localStorage.setItem("lp_c_"+key,JSON.stringify(next));}catch{};},[data,key]);return[data,save];}
function genAsiento(tipo,monto,cuentaContable,cuentaPago,condicion){const m=Number(monto)||0;if(tipo==="COMPRA"){if(condicion==="ANTICIPO")return[{cod:"1010201002",debe:m,haber:0},{cod:cuentaPago||"1010101001",debe:0,haber:m}];if(condicion==="CREDITO")return[{cod:cuentaContable,debe:m,haber:0},{cod:"2010101001",debe:0,haber:m}];return[{cod:cuentaContable,debe:m,haber:0},{cod:cuentaPago||"1010101001",debe:0,haber:m}];}if(tipo==="VENTA"){if(condicion==="CREDITO")return[{cod:"1010201001",debe:m,haber:0},{cod:cuentaContable,debe:0,haber:m}];return[{cod:cuentaPago||"1010101001",debe:m,haber:0},{cod:cuentaContable,debe:0,haber:m}];}if(tipo==="PAGO")return[{cod:"2010101001",debe:m,haber:0},{cod:cuentaPago||"1010101001",debe:0,haber:m}];return[];}
function Bdg({color,children,xs}){const map={green:[T.greenGlow,T.green],red:[T.redDim,T.red],blue:[T.blueDim,T.blue],gold:[T.goldDim,T.gold],purple:[T.purpleDim,T.purple]};const[bg,fg]=map[color]||["rgba(107,140,114,0.1)",T.textSub];return<span style={{padding:xs?"2px 7px":"3px 10px",borderRadius:20,fontSize:xs?10:11,fontWeight:700,background:bg,color:fg,display:"inline-block",lineHeight:1.5}}>{children}</span>;}
function Btn({children,onClick,v="primary",sz="md",full,disabled}){const[h,sh]=useState(false);const p={xs:"5px 10px",sm:"7px 14px",md:"10px 18px",lg:"13px 26px"}[sz];const fs={xs:10,sm:11,md:13,lg:14}[sz];const vs={primary:{background:h?"#5ED98A":T.green,color:"#091A10"},danger:{background:h?"#E86666":T.red,color:"#fff"},ghost:{background:h?T.border:"transparent",color:T.textSub,border:`1px solid ${T.border}`},outline:{background:h?T.greenGlow:"transparent",color:T.green,border:`1px solid ${T.green}`},warn:{background:h?"rgba(217,85,85,0.2)":T.redDim,color:T.red,border:`1px solid rgba(217,85,85,0.3)`}};return<button style={{padding:p,fontSize:fs,fontWeight:600,borderRadius:10,border:"none",cursor:disabled?"not-allowed":"pointer",display:"inline-flex",alignItems:"center",gap:5,transition:"all 0.15s",width:full?"100%":"auto",justifyContent:full?"center":"flex-start",opacity:disabled?0.5:1,fontFamily:"inherit",...vs[v]}} onClick={onClick} disabled={disabled} onMouseEnter={()=>sh(true)} onMouseLeave={()=>sh(false)}>{children}</button>;}
function Inp({label,value,onChange,type="text",placeholder,required,options,rows}){const s={background:"#0B100D",border:`1px solid ${T.border}`,borderRadius:10,padding:"11px 14px",color:T.text,fontSize:13,width:"100%",outline:"none",fontFamily:"inherit",boxSizing:"border-box"};return<div>{label&&<label style={{fontSize:11,fontWeight:700,color:T.textSub,marginBottom:5,display:"block",textTransform:"uppercase",letterSpacing:"0.6px"}}>{label}{required&&<span style={{color:T.red}}> *</span>}</label>}{options?<select style={s} value={value||""} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o.v!=null?o.v:o} value={o.v!=null?o.v:o}>{o.l!=null?o.l:o}</option>)}</select>:rows?<textarea style={{...s,minHeight:rows*26,resize:"vertical"}} value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>:<input style={s} type={type} value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}</div>;}
function AC({label,value,onChange,lista,placeholder,required,getLabel,renderItem}){const[texto,setTexto]=useState("");const[abierto,setAbierto]=useState(false);const caja=useRef(null);useEffect(()=>{if(value){const etq=getLabel?getLabel(value):String(value);setTexto(etq);}else{setTexto("");}},[value]);useEffect(()=>{const fn=e=>{if(caja.current&&!caja.current.contains(e.target))setAbierto(false);};document.addEventListener("mousedown",fn);return()=>document.removeEventListener("mousedown",fn);},[]);const filtrados=useMemo(()=>{if(!texto||texto.length<1)return lista.slice(0,8);const q=texto.toLowerCase();return lista.filter(item=>{const etq=getLabel?getLabel(item):String(item);return etq.toLowerCase().includes(q);}).slice(0,12);},[texto,lista,getLabel]);const seleccionar=item=>{const etq=getLabel?getLabel(item):String(item);setTexto(etq);onChange(item);setAbierto(false);};return<div ref={caja} style={{position:"relative"}}>{label&&<label style={{fontSize:11,fontWeight:700,color:T.textSub,marginBottom:5,display:"block",textTransform:"uppercase",letterSpacing:"0.6px"}}>{label}{required&&<span style={{color:T.red}}> *</span>}</label>}<input value={texto} onChange={e=>{setTexto(e.target.value);onChange(null);setAbierto(true);}} onFocus={()=>setAbierto(true)} placeholder={placeholder||"Escribir para buscar..."} style={{background:"#0B100D",border:`1px solid ${abierto?T.green:T.border}`,borderRadius:10,padding:"11px 14px",color:T.text,fontSize:13,width:"100%",outline:"none",fontFamily:"inherit",boxSizing:"border-box",transition:"border 0.15s"}}/>{abierto&&filtrados.length>0&&<div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:T.surface,border:`1px solid ${T.borderL}`,borderRadius:10,zIndex:999,maxHeight:200,overflowY:"auto",boxShadow:"0 8px 24px rgba(0,0,0,0.5)"}}>{filtrados.map((item,i)=><div key={i} onMouseDown={e=>{e.preventDefault();seleccionar(item);}} style={{padding:"10px 14px",cursor:"pointer",borderBottom:`1px solid ${T.border}`,fontSize:13}} onMouseEnter={e=>e.currentTarget.style.background=T.cardH} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>{renderItem?renderItem(item):(getLabel?getLabel(item):String(item))}</div>)}</div>}{abierto&&texto.length>1&&filtrados.length===0&&<div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:T.surface,border:`1px solid ${T.border}`,borderRadius:10,zIndex:999,padding:"12px 14px",fontSize:12,color:T.textSub}}>Sin resultados para "{texto}"</div>}</div>;}
