function LibroMayor({asientos,plan}){const[sel,setSel]=useState("");const getNom=cod=>plan.find(c=>c.cod===cod)?.nom||cod;const tColor={ACTIVO:T.green,PASIVO:T.red,PATRIMONIO:T.blue,INGRESO:T.gold,EGRESO:T.purple};const movs=useMemo(()=>{if(!sel)return[];return asientos.flatMap(a=>a.lineas.filter(l=>l.cod===sel).map(l=>({fecha:a.fecha,glosa:a.glosa,debe:l.debe,haber:l.haber}))).sort((a,b)=>a.fecha>b.fecha?1:-1);},[asientos,sel]);const totalD=movs.reduce((a,b)=>a+b.debe,0);const totalH=movs.reduce((a,b)=>a+b.haber,0);const saldo=totalD-totalH;const cuenta=plan.find(c=>c.cod===sel);const conMovs=useMemo(()=>{const set=new Set(asientos.flatMap(a=>a.lineas.map(l=>l.cod)));return plan.filter(c=>set.has(c.cod));},[asientos,plan]);return<div><Sec title="Libro Mayor 📒" sub="Movimientos por cuenta"/><AC label="Seleccionar Cuenta" value={sel?plan.find(c=>c.cod===sel)?.nom||sel:""} onChange={item=>{if(item&&item.cod)setSel(item.cod);}} lista={plan} placeholder="Buscar cuenta..." getLabel={item=>typeof item==="object"&&item?.nom?item.nom:typeof item==="string"?item:""} renderItem={c=><div><div style={{fontWeight:600,fontSize:12}}>{c.nom}</div><div style={{fontSize:10,color:T.textSub}}>{c.cod} · {c.tipo}</div></div>}/><div style={{marginTop:14}}/>{!sel&&conMovs.length>0&&<Card><div style={{fontWeight:700,fontSize:13,marginBottom:12}}>Cuentas con Movimientos</div>{conMovs.map(c=>{const ms=asientos.flatMap(a=>a.lineas.filter(l=>l.cod===c.cod));const d=ms.reduce((a,b)=>a+b.debe,0),h=ms.reduce((a,b)=>a+b.haber,0),s=d-h;return<div key={c.cod} onClick={()=>setSel(c.cod)} style={{display:"flex",justifyContent:"space-between",padding:"10px 0",borderBottom:`1px solid ${T.border}`,cursor:"pointer"}}><div><div style={{fontSize:13,fontWeight:600}}>{c.nom}</div><div style={{fontSize:10,color:T.textMuted}}>{c.cod} · <span style={{color:tColor[c.tipo]}}>{c.tipo}</span></div></div><div style={{textAlign:"right"}}><div style={{fontSize:13,fontWeight:700,color:s>=0?T.green:T.red}}>Bs {fmt$(Math.abs(s))}</div><Bdg color={s>=0?"green":"red"} xs>{s>=0?"DB":"CR"}</Bdg></div></div>;})}</Card>}{sel&&cuenta&&<><Card style={{marginBottom:14,borderLeft:`3px solid ${tColor[cuenta.tipo]||T.blue}`}}><div style={{fontWeight:700,fontSize:15,marginBottom:3}}>{cuenta.nom}</div><div style={{fontSize:11,color:T.textSub,marginBottom:14}}>{cuenta.cod} · {cuenta.tipo} · {cuenta.grupo}</div><G3 gap={8}><div style={{textAlign:"center",padding:"10px",background:T.bg,borderRadius:10}}><div style={{fontSize:10,color:T.textSub,marginBottom:3}}>DÉBITO</div><div style={{fontSize:15,fontWeight:800,color:T.green}}>Bs {fmt$(totalD)}</div></div><div style={{textAlign:"center",padding:"10px",background:T.bg,borderRadius:10}}><div style={{fontSize:10,color:T.textSub,marginBottom:3}}>CRÉDITO</div><div style={{fontSize:15,fontWeight:800,color:T.red}}>Bs {fmt$(totalH)}</div></div><div style={{textAlign:"center",padding:"10px",background:T.bg,borderRadius:10}}><div style={{fontSize:10,color:T.textSub,marginBottom:3}}>SALDO</div><div style={{fontSize:15,fontWeight:800,color:saldo>=0?T.green:T.red}}>Bs {fmt$(Math.abs(saldo))}</div></div></G3></Card><div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden",marginBottom:12}}><div style={{display:"grid",gridTemplateColumns:"80px 1fr 68px 68px 68px",gap:4,padding:"9px 14px",background:T.surface,fontSize:10,fontWeight:700,color:T.textSub,textTransform:"uppercase"}}><span>Fecha</span><span>Glosa</span><span style={{textAlign:"right"}}>Débito</span><span style={{textAlign:"right"}}>Crédito</span><span style={{textAlign:"right"}}>Saldo</span></div>{movs.length===0&&<div style={{padding:"20px",textAlign:"center",color:T.textMuted,fontSize:13}}>Sin movimientos</div>}{movs.reduce((acc,m)=>{const s=(acc.length>0?acc[acc.length-1].sal:0)+m.debe-m.haber;acc.push({...m,sal:s});return acc;},[]).map((m,i)=><div key={i} style={{display:"grid",gridTemplateColumns:"80px 1fr 68px 68px 68px",gap:4,padding:"9px 14px",borderTop:`1px solid ${T.border}`,fontSize:11}}><span style={{color:T.textSub}}>{fmtD(m.fecha)}</span><span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontSize:12}}>{m.glosa}</span><span style={{textAlign:"right",color:m.debe>0?T.green:T.textMuted}}>{m.debe>0?fmt$(m.debe):"—"}</span><span style={{textAlign:"right",color:m.haber>0?T.red:T.textMuted}}>{m.haber>0?fmt$(m.haber):"—"}</span><span style={{textAlign:"right",fontWeight:600,color:m.sal>=0?T.green:T.red}}>{fmt$(Math.abs(m.sal))}</span></div>)}</div><Btn v="ghost" sz="sm" onClick={()=>setSel("")}>← Ver todas</Btn></>}</div>;}
function EstadoResultados({asientos,plan}){const calc=tipo=>plan.filter(c=>c.tipo===tipo).map(c=>{const ms=asientos.flatMap(a=>a.lineas.filter(l=>l.cod===c.cod));const d=ms.reduce((a,b)=>a+b.debe,0),h=ms.reduce((a,b)=>a+b.haber,0);return{...c,saldo:tipo==="INGRESO"?h-d:d-h};}).filter(c=>c.saldo!==0);const ing=calc("INGRESO"),egr=calc("EGRESO");const ti=ing.reduce((a,b)=>a+b.saldo,0),te=egr.reduce((a,b)=>a+b.saldo,0),res=ti-te;const grupos=[...new Set(egr.map(e=>e.grupo))];return<div><Sec title="Estado de Resultados 📊"/><G2 gap={10}><Stat icon="📈" label="Ingresos" value={`Bs ${fmt$(ti)}`} accent={T.green}/><Stat icon="📉" label="Egresos" value={`Bs ${fmt$(te)}`} accent={T.red}/></G2><Card style={{marginTop:12,marginBottom:14,borderLeft:`3px solid ${res>=0?T.green:T.red}`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{fontSize:11,color:T.textSub}}>RESULTADO</div><div style={{fontSize:28,fontWeight:900,color:res>=0?T.green:T.red,marginTop:2}}>Bs {fmt$(Math.abs(res))}</div></div><Bdg color={res>=0?"green":"red"}>{res>=0?"UTILIDAD":"PÉRDIDA"}</Bdg></div>{ti>0&&<div style={{marginTop:10}}><Bar pct={Math.max(0,Math.round((res/ti)*100))} color={res>=0?T.green:T.red} h={6}/><div style={{fontSize:11,color:T.textSub,marginTop:3}}>Margen: {Math.round((res/ti)*100)}%</div></div>}</Card><Card style={{marginBottom:12}}><div style={{fontWeight:700,fontSize:13,color:T.green,marginBottom:12}}>📈 INGRESOS</div>{ing.length===0&&<div style={{fontSize:12,color:T.textMuted}}>Sin ingresos</div>}{ing.map(c=><div key={c.cod} style={{display:"flex",justifyContent:"space-between",padding:"7px 0",borderBottom:`1px solid ${T.border}`}}><div><div style={{fontSize:13}}>{c.nom}</div><div style={{fontSize:10,color:T.textMuted}}>{c.grupo}</div></div><span style={{fontSize:13,fontWeight:700,color:T.green}}>Bs {fmt$(c.saldo)}</span></div>)}<div style={{display:"flex",justifyContent:"space-between",padding:"10px 0 0",fontWeight:800,fontSize:14}}><span>TOTAL</span><span style={{color:T.green}}>Bs {fmt$(ti)}</span></div></Card><Card><div style={{fontWeight:700,fontSize:13,color:T.red,marginBottom:12}}>📉 EGRESOS</div>{egr.length===0&&<div style={{fontSize:12,color:T.textMuted}}>Sin egresos</div>}{grupos.map(g=>{const items=egr.filter(e=>e.grupo===g);const sub=items.reduce((a,b)=>a+b.saldo,0);return<div key={g} style={{marginBottom:10}}><div style={{fontSize:10,fontWeight:700,color:T.textSub,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:4,paddingBottom:3,borderBottom:`1px solid ${T.border}`}}>{g}</div>{items.map(c=><div key={c.cod} style={{display:"flex",justifyContent:"space-between",padding:"5px 0 5px 8px"}}><span style={{fontSize:12,color:T.textSub}}>{c.nom}</span><span style={{fontSize:12,fontWeight:600,color:T.red}}>Bs {fmt$(c.saldo)}</span></div>)}<div style={{display:"flex",justifyContent:"space-between",padding:"4px 0 4px 8px",fontWeight:700,fontSize:11}}><span style={{color:T.textMuted}}>Subtotal</span><span style={{color:T.red}}>Bs {fmt$(sub)}</span></div></div>;})} <div style={{display:"flex",justifyContent:"space-between",padding:"10px 0 0",fontWeight:800,fontSize:14,borderTop:`1px solid ${T.border}`}}><span>TOTAL</span><span style={{color:T.red}}>Bs {fmt$(te)}</span></div></Card></div>;}
function Balance({asientos,plan}){const calcG=tipo=>{const gs={};plan.filter(c=>c.tipo===tipo).forEach(c=>{const ms=asientos.flatMap(a=>a.lineas.filter(l=>l.cod===c.cod));const d=ms.reduce((a,b)=>a+b.debe,0),h=ms.reduce((a,b)=>a+b.haber,0);const s=tipo==="ACTIVO"?d-h:h-d;if(s!==0){if(!gs[c.grupo])gs[c.grupo]=[];gs[c.grupo].push({...c,saldo:s});}});return gs;};const act=calcG("ACTIVO"),pas=calcG("PASIVO"),pat=calcG("PATRIMONIO");const ta=Object.values(act).flat().reduce((a,b)=>a+b.saldo,0);const tp=Object.values(pas).flat().reduce((a,b)=>a+b.saldo,0);const tpt=Object.values(pat).flat().reduce((a,b)=>a+b.saldo,0);const cuadra=Math.abs(ta-(tp+tpt))<0.01;const Bloque=({titulo,gs,total,color})=><Card style={{marginBottom:12,borderLeft:`3px solid ${color}`}}><div style={{fontWeight:800,fontSize:13,color,marginBottom:12}}>{titulo}</div>{Object.keys(gs).length===0&&<div style={{fontSize:12,color:T.textMuted}}>Sin movimientos</div>}{Object.entries(gs).map(([g,items])=><div key={g} style={{marginBottom:8}}><div style={{fontSize:10,fontWeight:700,color:T.textSub,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:4}}>{g}</div>{items.map(c=><div key={c.cod} style={{display:"flex",justifyContent:"space-between",padding:"6px 0 6px 8px",borderBottom:`1px solid ${T.border}`}}><span style={{fontSize:12,color:T.textSub}}>{c.nom}</span><span style={{fontSize:12,fontWeight:600,color}}>Bs {fmt$(c.saldo)}</span></div>)}</div>)}<div style={{display:"flex",justifyContent:"space-between",padding:"10px 0 0",fontWeight:800,fontSize:14,borderTop:`1px solid ${T.border}`}}><span>TOTAL</span><span style={{color}}>Bs {fmt$(total)}</span></div></Card>;return<div><Sec title="Balance General 📋"/><G2 gap={10}><Stat icon="🏦" label="Total Activo" value={`Bs ${fmt$(ta)}`} accent={T.green}/><Stat icon="💳" label="Pasivo + Patrimonio" value={`Bs ${fmt$(tp+tpt)}`} accent={cuadra?T.green:T.red} sub={cuadra?"✓ Cuadra":"⚠ Verificar"}/></G2><div style={{marginTop:12}}><Bloque titulo="ACTIVO" gs={act} total={ta} color={T.green}/><Bloque titulo="PASIVO" gs={pas} total={tp} color={T.red}/><Bloque titulo="PATRIMONIO" gs={pat} total={tpt} color={T.blue}/></div><Card style={{borderLeft:`3px solid ${cuadra?T.green:T.red}`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{fontWeight:800,fontSize:14}}>ACTIVO = PASIVO + PATRIMONIO</div><div style={{fontSize:12,color:T.textSub,marginTop:3}}>Bs {fmt$(ta)} = Bs {fmt$(tp)} + Bs {fmt$(tpt)}</div></div><Bdg color={cuadra?"green":"red"}>{cuadra?"✓ CUADRA":"⚠ NO CUADRA"}</Bdg></div></Card></div>;}
const TABS=[["dashboard","Resumen","🏠"],["compras","Compras","🛒"],["ventas","Ventas","💚"],["pagos","Pagos","💸"],["mayor","Libro Mayor","📒"],["resultados","Resultados","📊"],["balance","Balance","📋"],["proveedores","Proveedores","🏢"],["clientes","Clientes","👥"],["plan","Plan Cuentas","📑"]];
export default function ContabilidadLP(){const[tab,setTab]=useState("dashboard");const[compras,setCompras]=useLS("compras",[]);const[ventas,setVentas]=useLS("ventas",[]);const[ordenes,setOrdenes]=useLS("ordenes",[]);const[asientos,setAsientos]=useLS("asientos",[]);const[proveedores,setProveedores]=useLS("proveedores",[]);const[clientes,setClientes]=useLS("clientes",[]);const[plan,setPlan]=useLS("plan_cuentas",PLAN_BASE);const tv=ventas.reduce((a,b)=>a+Number(b.monto||0),0);const tc=compras.reduce((a,b)=>a+Number(b.monto||0),0);const res=tv-tc;return<div style={{fontFamily:"'DM Sans','Helvetica Neue',sans-serif",background:T.bg,color:T.text,minHeight:"100vh",display:"flex",flexDirection:"column"}}><header style={{background:T.surface,borderBottom:`1px solid ${T.border}`,padding:"0 18px",height:58,display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:100}}><div style={{display:"flex",alignItems:"center",gap:10}}><div style={{width:34,height:34,borderRadius:9,background:`linear-gradient(135deg,${T.green},${T.greenDim})`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:17}}>📒</div><div><div style={{fontSize:14,fontWeight:800}}>La Ponderosa</div><div style={{fontSize:9,color:T.textMuted,textTransform:"uppercase",letterSpacing:"1.5px"}}>Sistema Contable</div></div></div><div style={{display:"flex",gap:8,alignItems:"center"}}><div style={{textAlign:"right"}}><div style={{fontSize:10,color:T.textSub}}>Resultado</div><div style={{fontSize:13,fontWeight:800,color:res>=0?T.green:T.red}}>Bs {fmt$(Math.abs(res))}</div></div><Bdg color={res>=0?"green":"red"}>{res>=0?"UTIL.":"PÉRD."}</Bdg></div></header><nav style={{background:T.surface,borderBottom:`1px solid ${T.border}`,display:"flex",overflowX:"auto",scrollbarWidth:"none",padding:"0 8px"}}>{TABS.map(([k,l,i])=><button key={k} onClick={()=>setTab(k)} style={{padding:"12px 12px",fontSize:11,fontWeight:tab===k?700:400,color:tab===k?T.green:T.textSub,borderBottom:tab===k?`2px solid ${T.green}`:"2px solid transparent",cursor:"pointer",whiteSpace:"nowrap",display:"flex",alignItems:"center",gap:4,background:"none",border:"none",fontFamily:"inherit",outline:"none"}}>{i} {l}</button>)}</nav><main style={{flex:1,padding:"20px 16px",maxWidth:860,margin:"0 auto",width:"100%",boxSizing:"border-box"}}>{tab==="dashboard"&&<Dashboard compras={compras} ventas={ventas} ordenes={ordenes} proveedores={proveedores} clientes={clientes} plan={plan} setTab={setTab}/>}{tab==="compras"&&<Compras compras={compras} setCompras={setCompras} asientos={asientos} setAsientos={setAsientos} proveedores={proveedores} setProveedores={setProveedores} plan={plan}/>}{tab==="ventas"&&<Ventas ventas={ventas} setVentas={setVentas} asientos={asientos} setAsientos={setAsientos} clientes={clientes} setClientes={setClientes} plan={plan}/>}{tab==="pagos"&&<OrdenesPago compras={compras} setCompras={setCompras} ordenes={ordenes} setOrdenes={setOrdenes} asientos={asientos} setAsientos={setAsientos} plan={plan}/>}{tab==="mayor"&&<LibroMayor asientos={asientos} plan={plan}/>}{tab==="resultados"&&<EstadoResultados asientos={asientos} plan={plan}/>}{tab==="balance"&&<Balance asientos={asientos} plan={plan}/>}{tab==="proveedores"&&<Proveedores proveedores={proveedores} setProveedores={setProveedores} compras={compras}/>}{tab==="clientes"&&<Clientes clientes={clientes} setClientes={setClientes} ventas={ventas}/>}{tab==="plan"&&<PlanCuentas plan={plan} setPlan={setPlan}/>}</main><div style={{textAlign:"center",padding:"12px",fontSize:10,color:T.textMuted,borderTop:`1px solid ${T.border}`}}>La Ponderosa · Sistema Contable v3.0</div></div>;}
